//! CRUD Gateway code generator — rusqlite (SQLite) backend.
//!
//! `generate_crud_gateway_rusqlite(&CrudGatewayDecl) -> String`
//!
//! Produces a complete generated `.rs` file containing:
//! - `// 🤖 GENERATED BY FORGE` header
//! - `row_to_X` functions for rusqlite row-to-struct mapping
//! - DB struct `impl` block with `migrate()` + all CRUD methods (sync)
//! - Helper enum-mapping functions
//! - Custom ops trait (Generation Gap Pattern)
//!
//! Key differences from the PostgreSQL generator:
//! - Sync (`fn` not `async fn`)
//! - `?N` placeholders, `params![]` macro
//! - Manual `row.get("col")` instead of `#[derive(FromRow)]`
//! - SQLite types via quarks::type_map::sqlite_ddl_type

use nc_jarvis_ir::crud::*;

use crate::rust::atoms::ddl_column::{gen_sqlite_add_column, gen_sqlite_ddl_column};
use crate::rust::atoms::row_to::gen_row_to;

// ---------------------------------------------------------------------------
// Public entry point
// ---------------------------------------------------------------------------

/// Generate complete rusqlite CRUD source from a CrudGatewayDecl.
pub fn generate_crud_gateway_rusqlite(decl: &CrudGatewayDecl) -> String {
    let mut out = String::with_capacity(16384);

    gen_header(&mut out);
    gen_imports(&mut out);
    out.push('\n');

    // row_to_X functions (one per table with row-type)
    for table in &decl.tables {
        if let Some(rt) = &table.row_type {
            gen_row_to(&mut out, 0, table, rt);
            out.push('\n');
        }
    }

    // DB struct + impl
    w(&mut out, 0, &format!("impl {} {{", decl.gateway_struct));

    gen_migrate(&mut out, decl);

    // Collect custom ops for trait generation
    let mut custom_ops: Vec<(&TableDecl, &CrudOpDecl)> = Vec::new();

    for table in &decl.tables {
        let has_standard = table.ops.iter().any(|op| op.kind != CrudOpKind::Custom);
        if has_standard {
            w(
                &mut out,
                1,
                &format!("// ========== {} ==========\n", table.name),
            );
        }
        for op in &table.ops {
            if op.kind == CrudOpKind::Custom {
                custom_ops.push((table, op));
            } else {
                gen_crud_op(&mut out, table, op);
                out.push('\n');
            }
        }
    }

    w(&mut out, 0, "}\n");

    // Helper functions
    for helper in &decl.helpers {
        gen_helper(&mut out, helper);
    }

    // Trait contract for custom ops (Generation Gap Pattern)
    if !custom_ops.is_empty() {
        gen_custom_trait(&mut out, &custom_ops, &decl.gateway_struct);
    }

    out
}

// ---------------------------------------------------------------------------
// Header + imports
// ---------------------------------------------------------------------------

fn gen_header(out: &mut String) {
    crate::common::forge_header(out, "rust", "intent-db.lisp (crud-gateway, backend: sqlite)");
    out.push('\n');
}

fn gen_imports(out: &mut String) {
    out.push_str("#![allow(unused_imports, dead_code)]\n\n");
    out.push_str("use rusqlite::{params, OptionalExtension};\n");
    out.push_str("use crate::db::error::DbResult;\n");
}

// ---------------------------------------------------------------------------
// migrate()
// ---------------------------------------------------------------------------

fn gen_migrate(out: &mut String, decl: &CrudGatewayDecl) {
    w(out, 1, "pub fn migrate(&self) -> DbResult<()> {");
    w(out, 2, "let conn = self.conn();");
    out.push('\n');

    for table in &decl.tables {
        // CREATE TABLE IF NOT EXISTS
        let mut ddl = format!("CREATE TABLE IF NOT EXISTS {} (\\n", table.name);
        let mut col_defs = Vec::new();

        for col in &table.columns {
            col_defs.push(format!("    {}", gen_sqlite_ddl_column(col)));
        }

        // Composite primary key
        if let Some(ref cpk) = table.composite_pk {
            col_defs.push(format!("    PRIMARY KEY ({})", cpk.columns.join(", ")));
        }

        // Unique constraints
        for uc in &table.unique_constraints {
            col_defs.push(format!("    UNIQUE({})", uc.columns.join(", ")));
        }

        ddl.push_str(&col_defs.join(",\\n"));
        ddl.push_str("\\n)");

        w(out, 2, &format!("conn.execute_batch(\"{ddl}\")?;\n"));

        // Column evolution: PRAGMA table_info → ADD COLUMN for new fields only
        // (SQLite cannot modify or delete columns — only ADD COLUMN is safe)
        w(
            out,
            2,
            &format!(
                "let existing_cols: Vec<String> = conn.prepare(\"PRAGMA table_info({})\")?",
                table.name
            ),
        );
        w(
            out,
            3,
            ".query_map([], |row| row.get::<_, String>(1))?",
        );
        w(out, 3, ".filter_map(|r| r.ok())");
        w(out, 3, ".collect();\n");

        for col in &table.columns {
            let add_sql = gen_sqlite_add_column(&table.name, col);
            w(
                out,
                2,
                &format!(
                    "if !existing_cols.iter().any(|c| c == \"{}\") {{",
                    col.name
                ),
            );
            w(
                out,
                3,
                &format!("conn.execute_batch(\"{add_sql}\")?;"),
            );
            w(out, 2, "}");
        }
        out.push('\n');

        // CREATE INDEX
        for idx in &table.indexes {
            let unique = if idx.unique { "UNIQUE " } else { "" };
            let sql = format!(
                "CREATE {}INDEX IF NOT EXISTS {} ON {}({})",
                unique,
                idx.name,
                table.name,
                idx.columns.join(", ")
            );
            w(out, 2, &format!("conn.execute_batch(\"{sql}\")?;"));
        }
        out.push('\n');
    }

    w(out, 2, "Ok(())");
    w(out, 1, "}\n");
}

// ---------------------------------------------------------------------------
// CRUD op dispatch
// ---------------------------------------------------------------------------

fn gen_crud_op(out: &mut String, table: &TableDecl, op: &CrudOpDecl) {
    match op.kind {
        CrudOpKind::Insert => gen_insert(out, table, op),
        CrudOpKind::InsertStruct => gen_insert_struct(out, table, op),
        CrudOpKind::SelectOne => gen_select_one(out, table, op),
        CrudOpKind::SelectMany => gen_select_many(out, table, op),
        CrudOpKind::SelectJson => gen_select_json(out, table, op),
        CrudOpKind::Update => gen_update(out, table, op),
        CrudOpKind::UpdateDynamic => gen_update_dynamic(out, table, op),
        CrudOpKind::UpdateCas => gen_update_cas(out, table, op),
        CrudOpKind::Delete => gen_delete(out, table, op),
        CrudOpKind::Upsert => gen_upsert(out, table, op),
        CrudOpKind::Count => gen_count(out, table, op),
        CrudOpKind::SyncBatch => gen_sync_batch(out, table, op),
        CrudOpKind::Custom => gen_custom(out, table, op),
    }
}

// ---------------------------------------------------------------------------
// Insert
// ---------------------------------------------------------------------------

fn gen_insert(out: &mut String, table: &TableDecl, op: &CrudOpDecl) {
    let sig = build_fn_sig(op);
    w(out, 1, &sig);

    // Auto-generated fields
    for auto in &op.auto_fields {
        if let Some(ref expr) = auto.via_expr {
            w(out, 2, &format!("let {} = {};", auto.name, expr));
        }
        if let Some(ref query) = auto.via_query {
            w(
                out,
                2,
                &format!("let {}: i32 = conn.query_row(\"{query}\",", auto.name),
            );
            if !op.params.is_empty() {
                w(out, 3, &format!("params![{}],", op.params[0].name));
            } else {
                w(out, 3, "[],");
            }
            w(out, 3, "|row| row.get(0))?;");
        }
    }

    let mut columns = Vec::new();
    let mut placeholders = Vec::new();
    let mut binds = Vec::new();
    let mut idx = 1u32;

    for auto in &op.auto_fields {
        columns.push(auto.name.clone());
        placeholders.push(format!("?{idx}"));
        binds.push(auto.name.clone());
        idx += 1;
    }

    for (col, val) in &op.defaults {
        columns.push(col.clone());
        placeholders.push(format!("?{idx}"));
        binds.push(format!("\"{}\"", val));
        idx += 1;
    }

    for param in &op.params {
        columns.push(param.name.clone());
        placeholders.push(format!("?{idx}"));
        if let Some(ref cast) = param.cast_to {
            binds.push(format!("{} as {}", param.name, cast));
        } else {
            binds.push(param.name.clone());
        }
        idx += 1;
    }

    let sql = format!(
        "INSERT INTO {} ({}) VALUES ({})",
        table.name,
        columns.join(", "),
        placeholders.join(", ")
    );

    w(out, 2, "let conn = self.conn();");
    w(out, 2, &format!("conn.execute("));
    w(out, 3, &format!("\"{sql}\","));
    w(out, 3, &format!("params![{}],", binds.join(", ")));
    w(out, 2, ")?;");

    // Side effect
    if let Some(ref se) = op.side_effect {
        let se_sql = se.replace("$task_id", "?1");
        out.push('\n');
        w(
            out,
            2,
            &format!("conn.execute(\"{se_sql}\", params![task_id])?;"),
        );
    }

    // Return
    if op.returns == "()" {
        w(out, 2, "Ok(())");
    } else if op.returns == "String" {
        w(out, 2, "Ok(id)");
    } else {
        w(out, 2, &format!("Ok({} {{", op.returns));
        for col in &table.columns {
            let val = if op.auto_fields.iter().any(|a| a.name == col.name) {
                col.name.clone()
            } else if let Some((_, default_val)) = op.defaults.iter().find(|(k, _)| k == &col.name)
            {
                if let Some(rt) = &table.row_type {
                    if let Some(em) = rt.enum_maps.iter().find(|m| m.field == col.name) {
                        format!("{}::Idle /* default: {} */", em.target_type, default_val)
                    } else {
                        format!("\"{}\".to_string()", default_val)
                    }
                } else {
                    format!("\"{}\".to_string()", default_val)
                }
            } else if op.params.iter().any(|p| p.name == col.name) {
                col.name.clone()
            } else if col.nullable {
                "None".to_string()
            } else {
                format!("Default::default() /* TODO: {} */", col.name)
            };
            w(out, 3, &format!("{}: {},", col.name, val));
        }
        w(out, 2, "})");
    }

    w(out, 1, "}");
}

// ---------------------------------------------------------------------------
// InsertStruct
// ---------------------------------------------------------------------------

fn gen_insert_struct(out: &mut String, table: &TableDecl, op: &CrudOpDecl) {
    let sig = build_fn_sig(op);
    w(out, 1, &sig);

    let columns: Vec<&str> = table.columns.iter().map(|c| c.name.as_str()).collect();
    let placeholders: Vec<String> = (1..=columns.len()).map(|i| format!("?{i}")).collect();

    let param_name = if !op.params.is_empty() {
        &op.params[0].name
    } else {
        "item"
    };

    let sql = format!(
        "INSERT INTO {} ({}) VALUES ({})",
        table.name,
        columns.join(", "),
        placeholders.join(", ")
    );

    // Build bind expressions with type conversions
    let mut bind_exprs = Vec::new();
    for col in &table.columns {
        let expr = match col.col_type {
            ColumnType::Boolean => format!("{param_name}.{} as i32", col.name),
            ColumnType::Jsonb => {
                format!(
                    "serde_json::to_string(&{param_name}.{}).unwrap_or_else(|_| \"{{}}\".to_string())",
                    col.name
                )
            }
            _ => {
                // Check for enum converter
                if let Some(rt) = &table.row_type {
                    if let Some(em) = rt.enum_maps.iter().find(|m| m.field == col.name) {
                        // Use the to_str converter (name ending in _to_str)
                        let to_str = em.converter.replace("_from_str", "_to_str");
                        format!("{to_str}({param_name}.{})", col.name)
                    } else {
                        format!("{param_name}.{}", col.name)
                    }
                } else {
                    format!("{param_name}.{}", col.name)
                }
            }
        };
        bind_exprs.push(expr);
    }

    w(out, 2, "let conn = self.conn();");
    w(out, 2, "conn.execute(");
    w(out, 3, &format!("\"{sql}\","));
    w(out, 3, &format!("params![{}],", bind_exprs.join(", ")));
    w(out, 2, ")?;");
    w(out, 2, "Ok(())");
    w(out, 1, "}");
}

// ---------------------------------------------------------------------------
// SelectOne
// ---------------------------------------------------------------------------

fn gen_select_one(out: &mut String, table: &TableDecl, op: &CrudOpDecl) {
    let sig = build_fn_sig(op);
    w(out, 1, &sig);

    let select_cols = if op.select_cols.is_empty() {
        "*".to_string()
    } else {
        op.select_cols.join(", ")
    };

    let (where_clause, binds) = build_where(&op.where_clause, 1);
    let sql = format!(
        "SELECT {select_cols} FROM {}{where_clause}",
        table.name
    );

    let row_fn = table
        .row_type
        .as_ref()
        .map(|rt| rt.convert_fn.as_str())
        .unwrap_or("/* TODO: row_to_fn */");

    w(out, 2, "let conn = self.read_conn();");
    w(out, 2, "conn.query_row(");
    w(out, 3, &format!("\"{sql}\","));
    if binds.is_empty() {
        w(out, 3, "[],");
    } else {
        w(out, 3, &format!("params![{}],", binds.join(", ")));
    }
    w(out, 3, &format!("|row| {row_fn}(row),"));
    w(out, 2, ")");
    w(out, 2, ".optional()");
    w(out, 2, ".map_err(Into::into)");

    w(out, 1, "}");
}

// ---------------------------------------------------------------------------
// SelectMany
// ---------------------------------------------------------------------------

fn gen_select_many(out: &mut String, table: &TableDecl, op: &CrudOpDecl) {
    let sig = build_fn_sig(op);
    w(out, 1, &sig);

    let select_cols = if op.select_cols.is_empty() {
        "*".to_string()
    } else {
        op.select_cols.join(", ")
    };

    let (where_clause, mut binds) = build_where(&op.where_clause, 1);
    let mut next_idx = binds.len() as u32 + 1;

    let order = op
        .order
        .as_ref()
        .map(|o| format!(" ORDER BY {o}"))
        .unwrap_or_default();

    let limit_clause = if op.params.iter().any(|p| p.name == "limit") {
        let s = format!(" LIMIT ?{next_idx}");
        binds.push("limit".to_string());
        next_idx += 1;
        s
    } else if let Some(lim) = op.limit {
        format!(" LIMIT {lim}")
    } else {
        String::new()
    };

    let offset_clause = if op.params.iter().any(|p| p.name == "offset") {
        let s = format!(" OFFSET ?{next_idx}");
        binds.push("offset".to_string());
        s
    } else {
        String::new()
    };

    let sql = format!(
        "SELECT {select_cols} FROM {}{where_clause}{order}{limit_clause}{offset_clause}",
        table.name
    );

    let row_fn = table
        .row_type
        .as_ref()
        .map(|rt| rt.convert_fn.as_str())
        .unwrap_or("/* TODO: row_to_fn */");

    w(out, 2, "let conn = self.read_conn();");
    w(
        out,
        2,
        &format!("let mut stmt = conn.prepare(\"{sql}\")?;"),
    );

    if binds.is_empty() {
        w(
            out,
            2,
            &format!("let rows = stmt.query_map([], |row| {row_fn}(row))?;"),
        );
    } else {
        w(
            out,
            2,
            &format!(
                "let rows = stmt.query_map(params![{}], |row| {row_fn}(row))?;",
                binds.join(", ")
            ),
        );
    }

    if op.post_process.as_deref() == Some("reverse") {
        w(
            out,
            2,
            "let mut result: Vec<_> = rows.collect::<Result<Vec<_>, _>>().map_err(|e| -> DbResult<_> { Err(e.into()) })??;",
        );
        w(out, 2, "result.reverse();");
        w(out, 2, "Ok(result)");
    } else {
        w(
            out,
            2,
            "rows.collect::<Result<Vec<_>, _>>().map_err(Into::into)",
        );
    }

    w(out, 1, "}");
}

// ---------------------------------------------------------------------------
// SelectJson
// ---------------------------------------------------------------------------

fn gen_select_json(out: &mut String, table: &TableDecl, op: &CrudOpDecl) {
    let sig = build_fn_sig(op);
    w(out, 1, &sig);

    let (where_clause, binds) = build_where(&op.where_clause, 1);

    let order = op
        .order
        .as_ref()
        .map(|o| format!(" ORDER BY {o}"))
        .unwrap_or_default();

    let sql = format!(
        "SELECT * FROM {}{where_clause}{order}",
        table.name
    );

    // For SQLite, we query all columns and serialize to JSON in Rust
    let row_fn = table
        .row_type
        .as_ref()
        .map(|rt| rt.convert_fn.as_str())
        .unwrap_or("/* TODO */");

    w(out, 2, "let conn = self.read_conn();");
    w(
        out,
        2,
        &format!("let mut stmt = conn.prepare(\"{sql}\")?;"),
    );
    if binds.is_empty() {
        w(
            out,
            2,
            &format!("let rows = stmt.query_map([], |row| {row_fn}(row))?;"),
        );
    } else {
        w(
            out,
            2,
            &format!(
                "let rows = stmt.query_map(params![{}], |row| {row_fn}(row))?;",
                binds.join(", ")
            ),
        );
    }
    w(
        out,
        2,
        "let items: Vec<_> = rows.filter_map(|r| r.ok()).collect();",
    );
    w(
        out,
        2,
        "Ok(items.into_iter().map(|i| serde_json::to_value(&i).unwrap_or_default()).collect())",
    );

    w(out, 1, "}");
}

// ---------------------------------------------------------------------------
// Update
// ---------------------------------------------------------------------------

fn gen_update(out: &mut String, _table: &TableDecl, op: &CrudOpDecl) {
    let sig = build_fn_sig(op);
    w(out, 1, &sig);

    let mut set_parts = Vec::new();
    let mut binds = Vec::new();
    let mut idx = 1u32;

    for sf in &op.set_fields {
        if let Some(ref lit) = sf.literal {
            set_parts.push(format!("{} = {}", sf.column, lit));
        } else if let Some(ref via) = sf.via_fn {
            set_parts.push(format!("{} = {}", sf.column, via));
        } else {
            set_parts.push(format!("{} = ?{idx}", sf.column));
            if let Some(ref conv) = sf.converter {
                binds.push(format!(
                    "{}({})",
                    conv,
                    sf.param_name.as_deref().unwrap_or(&sf.column)
                ));
            } else {
                binds.push(sf.param_name.clone().unwrap_or_else(|| sf.column.clone()));
            }
            idx += 1;
        }
    }

    // WHERE clause binds
    for wp in &op.where_clause {
        binds.push(wp.bind_name.clone().unwrap_or_else(|| wp.name.clone()));
        idx += 1;
    }

    let where_parts: Vec<String> = op
        .where_clause
        .iter()
        .enumerate()
        .map(|(i, wp)| {
            let param_idx = binds.len() - op.where_clause.len() + i + 1;
            format!("{} = ?{param_idx}", wp.name)
        })
        .collect();

    let where_clause = if where_parts.is_empty() {
        String::new()
    } else {
        format!(" WHERE {}", where_parts.join(" AND "))
    };

    let table_name = &_table.name;
    let sql = format!(
        "UPDATE {table_name} SET {}{where_clause}",
        set_parts.join(", ")
    );

    w(out, 2, "let conn = self.conn();");
    w(out, 2, &format!("conn.execute("));
    w(out, 3, &format!("\"{sql}\","));
    w(out, 3, &format!("params![{}],", binds.join(", ")));
    w(out, 2, ")?;");
    w(out, 2, "Ok(())");
    w(out, 1, "}");
}

// ---------------------------------------------------------------------------
// UpdateDynamic — push_field! macro pattern
// ---------------------------------------------------------------------------

fn gen_update_dynamic(out: &mut String, table: &TableDecl, op: &CrudOpDecl) {
    let sig = build_fn_sig(op);
    w(out, 1, &sig);

    w(out, 2, "let mut fields = Vec::new();");
    w(
        out,
        2,
        "let mut values: Vec<Box<dyn rusqlite::types::ToSql>> = Vec::new();",
    );
    out.push('\n');

    for field in &op.dynamic_fields {
        w(
            out,
            2,
            &format!("if let Some(v) = updates[\"{field}\"].as_str() {{"),
        );
        w(
            out,
            3,
            &format!("fields.push(\"{field} = ?\".to_string());"),
        );
        w(out, 3, "values.push(Box::new(v.to_string()));");
        w(out, 2, "}");
    }

    out.push('\n');
    w(out, 2, "if fields.is_empty() { return Ok(()); }");
    out.push('\n');

    // Auto-set fields
    for (col, via) in &op.auto_set {
        // SQLite doesn't have now() — use datetime('now')
        let via_sqlite = via.replace("now()", "datetime('now')");
        w(
            out,
            2,
            &format!("fields.push(\"{col} = {via_sqlite}\".to_string());"),
        );
    }

    w(
        out,
        2,
        &format!(
            "let sql = format!(\"UPDATE {} SET {{}} WHERE id = ?\", fields.join(\", \"));",
            table.name
        ),
    );
    w(out, 2, "values.push(Box::new(id.to_string()));");
    out.push('\n');
    w(
        out,
        2,
        "let params: Vec<&dyn rusqlite::types::ToSql> = values.iter().map(|v| v.as_ref()).collect();",
    );
    w(out, 2, "let conn = self.conn();");
    w(out, 2, "conn.execute(&sql, params.as_slice())?;");
    w(out, 2, "Ok(())");
    w(out, 1, "}");
}

// ---------------------------------------------------------------------------
// UpdateCas — compare-and-swap with preconditions
// ---------------------------------------------------------------------------

fn gen_update_cas(out: &mut String, table: &TableDecl, op: &CrudOpDecl) {
    let sig = build_fn_sig(op);
    w(out, 1, &sig);

    let mut set_parts = Vec::new();
    let mut binds = Vec::new();
    let mut idx = 1u32;

    // WHERE pk
    for wp in &op.where_clause {
        binds.push(wp.name.clone());
        idx += 1;
    }

    // SET fields
    for sf in &op.set_fields {
        if let Some(ref lit) = sf.literal {
            set_parts.push(format!("{} = {}", sf.column, lit));
        } else if let Some(ref via) = sf.via_fn {
            let via_sqlite = via.replace("now()", "datetime('now')");
            set_parts.push(format!("{} = {}", sf.column, via_sqlite));
        } else if let Some(ref pn) = sf.param_name {
            set_parts.push(format!("{} = ?{idx}", sf.column));
            binds.push(pn.clone());
            idx += 1;
        }
    }

    let _ = idx;

    let where_pk: Vec<String> = op
        .where_clause
        .iter()
        .enumerate()
        .map(|(i, wp)| format!("{} = ?{}", wp.name, i + 1))
        .collect();

    let mut all_conditions = where_pk;
    all_conditions.extend(op.preconditions.iter().cloned());

    let sql = format!(
        "UPDATE {} SET {} WHERE {}",
        table.name,
        set_parts.join(", "),
        all_conditions.join(" AND ")
    );

    w(out, 2, "let conn = self.conn();");
    w(out, 2, &format!("let changes = conn.execute("));
    w(out, 3, &format!("\"{sql}\","));
    w(out, 3, &format!("params![{}],", binds.join(", ")));
    w(out, 2, ")?;");
    w(out, 2, "Ok(changes > 0)");
    w(out, 1, "}");
}

// ---------------------------------------------------------------------------
// Delete
// ---------------------------------------------------------------------------

fn gen_delete(out: &mut String, table: &TableDecl, op: &CrudOpDecl) {
    let sig = build_fn_sig(op);
    w(out, 1, &sig);

    let (where_clause, binds) = build_where(&op.where_clause, 1);
    let sql = format!("DELETE FROM {}{where_clause}", table.name);

    w(out, 2, "let conn = self.conn();");

    if op.returns == "bool" {
        w(out, 2, &format!("let changes = conn.execute("));
    } else {
        w(out, 2, &format!("conn.execute("));
    }
    w(out, 3, &format!("\"{sql}\","));
    if binds.is_empty() {
        w(out, 3, "[],");
    } else {
        w(out, 3, &format!("params![{}],", binds.join(", ")));
    }
    w(out, 2, ")?;");

    if op.returns == "bool" {
        w(out, 2, "Ok(changes > 0)");
    } else {
        w(out, 2, "Ok(())");
    }
    w(out, 1, "}");
}

// ---------------------------------------------------------------------------
// Upsert
// ---------------------------------------------------------------------------

fn gen_upsert(out: &mut String, table: &TableDecl, op: &CrudOpDecl) {
    let sig = build_fn_sig(op);
    w(out, 1, &sig);

    let mut columns = Vec::new();
    let mut placeholders = Vec::new();
    let mut binds = Vec::new();
    let mut idx = 1u32;

    for (i, param) in op.params.iter().enumerate() {
        let col_name = table
            .columns
            .get(i)
            .map(|c| c.name.as_str())
            .unwrap_or(&param.name);
        columns.push(col_name.to_string());
        placeholders.push(format!("?{idx}"));
        if let Some(ref cast) = param.cast_to {
            binds.push(format!("{} as {}", param.name, cast));
        } else {
            binds.push(param.name.clone());
        }
        idx += 1;
    }

    let conflict = op
        .on_conflict
        .as_deref()
        .unwrap_or("(id) DO NOTHING");

    // Adapt PG syntax to SQLite: $N → ?N in ON CONFLICT clause
    let conflict_sqlite = adapt_placeholders(conflict, &columns);

    let sql = format!(
        "INSERT INTO {} ({}) VALUES ({}) ON CONFLICT {conflict_sqlite}",
        table.name,
        columns.join(", "),
        placeholders.join(", ")
    );

    w(out, 2, "let conn = self.conn();");
    w(out, 2, "conn.execute(");
    w(out, 3, &format!("\"{sql}\","));
    w(out, 3, &format!("params![{}],", binds.join(", ")));
    w(out, 2, ")?;");

    if op.returns == "()" {
        w(out, 2, "Ok(())");
    } else {
        w(out, 2, "Ok(/* construct return */)");
    }
    w(out, 1, "}");
}

// ---------------------------------------------------------------------------
// Count
// ---------------------------------------------------------------------------

fn gen_count(out: &mut String, table: &TableDecl, op: &CrudOpDecl) {
    let sig = build_fn_sig(op);
    w(out, 1, &sig);

    let (where_clause, binds) = build_where(&op.where_clause, 1);
    let sql = format!("SELECT COUNT(*) FROM {}{where_clause}", table.name);

    w(out, 2, "let conn = self.read_conn();");
    if binds.is_empty() {
        w(
            out,
            2,
            &format!(
                "let count: i64 = conn.query_row(\"{sql}\", [], |row| row.get(0))?;"
            ),
        );
    } else {
        w(
            out,
            2,
            &format!(
                "let count: i64 = conn.query_row(\"{sql}\", params![{}], |row| row.get(0))?;",
                binds.join(", ")
            ),
        );
    }
    w(out, 2, "Ok(count)");
    w(out, 1, "}");
}

// ---------------------------------------------------------------------------
// SyncBatch
// ---------------------------------------------------------------------------

fn gen_sync_batch(out: &mut String, table: &TableDecl, op: &CrudOpDecl) {
    let sig = build_fn_sig(op);
    w(out, 1, &sig);

    w(out, 2, "let conn = self.conn();");

    if let Some(ref dw) = op.delete_where {
        let pk_param = op.params.first().map(|p| p.name.as_str()).unwrap_or("id");
        w(
            out,
            2,
            &format!(
                "conn.execute(\"DELETE FROM {} WHERE {dw}\", params![{pk_param}])?;",
                table.name
            ),
        );
        out.push('\n');
    }

    if let Some(ref each_var) = op.insert_each {
        let param_name = op
            .params
            .get(1)
            .map(|p| p.name.as_str())
            .unwrap_or("items");
        w(
            out,
            2,
            &format!("for {each_var} in {param_name} {{"),
        );
        w(out, 3, "// TODO: insert each row");
        w(out, 2, "}");
    }

    w(out, 2, "Ok(())");
    w(out, 1, "}");
}

// ---------------------------------------------------------------------------
// Custom
// ---------------------------------------------------------------------------

fn gen_custom(out: &mut String, _table: &TableDecl, op: &CrudOpDecl) {
    let sig = build_fn_sig(op);
    w(out, 1, &sig);

    if let Some(ref sql) = op.custom_sql {
        w(out, 2, &format!("// SQL: {sql}"));
    }
    if !op.custom_queries.is_empty() {
        for (name, sql) in &op.custom_queries {
            w(out, 2, &format!("// {name}: {sql}"));
        }
    }
    w(out, 2, "todo!(\"custom op — implement in custom.rs\")");

    w(out, 1, "}");
}

// ---------------------------------------------------------------------------
// Helper functions
// ---------------------------------------------------------------------------

fn gen_helper(out: &mut String, helper: &HelperFnDecl) {
    let param_type = &helper.param_type;
    let return_type = &helper.return_type;

    w(
        out,
        0,
        &format!(
            "fn {}({}: {param_type}) -> {return_type} {{",
            helper.name,
            if return_type.contains("&'static") {
                "status"
            } else {
                "s"
            },
        ),
    );

    if return_type.contains("&'static") {
        w(out, 1, "match status {");
        for (from, to) in &helper.mappings {
            w(out, 2, &format!("{param_type}::{from} => \"{to}\","));
        }
        w(out, 1, "}");
    } else {
        w(out, 1, "match s {");
        for (from, to) in &helper.mappings {
            w(out, 2, &format!("\"{from}\" => {return_type}::{to},"));
        }
        if let Some(ref d) = helper.default {
            w(out, 2, &format!("_ => {return_type}::{d},"));
        }
        w(out, 1, "}");
    }

    w(out, 0, "}\n");
}

// ---------------------------------------------------------------------------
// Custom ops → Trait contract (Generation Gap Pattern)
// ---------------------------------------------------------------------------

fn gen_custom_trait(
    out: &mut String,
    ops: &[(&TableDecl, &CrudOpDecl)],
    gateway_struct: &str,
) {
    w(
        out,
        0,
        "// ═══════════════════════════════════════════════════════════",
    );
    w(
        out,
        0,
        "// 🤖 GENERATED CONTRACT — implement in *_custom.rs",
    );
    w(
        out,
        0,
        "// These signatures are locked by intent-db.lisp declarations.",
    );
    w(
        out,
        0,
        "// Rust compiler enforces your impl matches these exactly.",
    );
    w(
        out,
        0,
        "// ═══════════════════════════════════════════════════════════\n",
    );

    w(
        out,
        0,
        &format!("pub trait {gateway_struct}CustomLogic {{"),
    );

    for (table, op) in ops {
        if let Some(ref sql) = op.custom_sql {
            w(out, 1, &format!("/// SQL: {sql}"));
        }
        if !op.custom_queries.is_empty() {
            for (name, sql) in &op.custom_queries {
                w(out, 1, &format!("/// {name}: {sql}"));
            }
        }
        if let Some(ref logic) = op.logic {
            w(out, 1, &format!("/// Logic: {logic}"));
        }
        w(out, 1, &format!("/// Table: {}", table.name));

        let mut params_str = String::from("&self");
        for wp in &op.where_clause {
            let name = wp.bind_name.as_deref().unwrap_or(&wp.name);
            params_str.push_str(&format!(", {}: {}", name, rust_param_type(&wp.rust_type)));
        }
        for p in &op.params {
            params_str.push_str(&format!(", {}: {}", p.name, rust_param_type(&p.rust_type)));
        }

        w(
            out,
            1,
            &format!(
                "fn {}({params_str}) -> DbResult<{}>;",
                op.name, op.returns
            ),
        );
        out.push('\n');
    }

    w(out, 0, "}\n");
}

// ---------------------------------------------------------------------------
// Shared utilities
// ---------------------------------------------------------------------------

fn rust_param_type(s: &str) -> &str {
    match s {
        "uuid" => "&str",
        "text" => "&str",
        "integer" | "int" => "i32",
        "bigint" => "i64",
        "boolean" | "bool" => "bool",
        "float8" => "f64",
        "jsonb" => "serde_json::Value",
        "timestamptz" => "&str",
        other => other,
    }
}

fn build_fn_sig(op: &CrudOpDecl) -> String {
    let mut params_str = String::from("&self");

    for wp in &op.where_clause {
        let name = wp.bind_name.as_deref().unwrap_or(&wp.name);
        params_str.push_str(&format!(", {}: {}", name, rust_param_type(&wp.rust_type)));
    }
    for p in &op.params {
        params_str.push_str(&format!(", {}: {}", p.name, rust_param_type(&p.rust_type)));
    }
    if op.kind == CrudOpKind::UpdateDynamic {
        params_str.push_str(", updates: &serde_json::Value");
    }
    if op.kind == CrudOpKind::UpdateCas {
        for sf in &op.set_fields {
            if let Some(ref pn) = sf.param_name {
                if let Some(ref rt) = sf.rust_type {
                    params_str.push_str(&format!(", {pn}: {rt}"));
                }
            }
        }
    }

    format!(
        "pub fn {}({params_str}) -> DbResult<{}> {{",
        op.name, op.returns
    )
}

fn build_where(params: &[ParamDecl], start_idx: u32) -> (String, Vec<String>) {
    if params.is_empty() {
        return (String::new(), vec![]);
    }
    let mut parts = Vec::new();
    let mut binds = Vec::new();
    for (i, p) in params.iter().enumerate() {
        let idx = start_idx + i as u32;
        parts.push(format!("{} = ?{idx}", p.name));
        binds.push(p.bind_name.clone().unwrap_or_else(|| p.name.clone()));
    }
    (format!(" WHERE {}", parts.join(" AND ")), binds)
}

/// Adapt PG-style `$N` placeholders to SQLite `?N` in ON CONFLICT clauses.
fn adapt_placeholders(conflict_clause: &str, _columns: &[String]) -> String {
    let mut result = conflict_clause.to_string();
    // Replace $N with ?N
    for i in (1..=20).rev() {
        result = result.replace(&format!("${i}"), &format!("?{i}"));
    }
    // Replace now() with datetime('now')
    result = result.replace("now()", "datetime('now')");
    result
}

fn w(out: &mut String, indent: usize, line: &str) {
    for _ in 0..indent {
        out.push_str("    ");
    }
    out.push_str(line);
    out.push('\n');
}

